const T=['CIJ','LASER','LCM','TIJ','TTO'],L=['Level 1','Level 2','Level 3','Unassessed'],C=['#8cae92','#4d927c','#184f46','#d9dcd3'];
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),mean=a=>a.length?a.reduce((s,x)=>s+x,0)/a.length:null,fmt=(v,n=1)=>v==null?'—':v.toLocaleString('en-IN',{maximumFractionDigits:n,minimumFractionDigits:n}),pct=v=>v==null?'—':fmt(v*100)+'%',opts=(id,a)=>$(id).innerHTML=a.map(x=>`<option>${esc(x)}</option>`).join('');
opts('zone',['All India',...new Set(DATA.roster.map(e=>e.zone).sort())]);opts('tech',['All technologies',...T]);opts('month',['All months',...new Set(DATA.events.map(e=>e.month).sort())]);
function scope(){return DATA.roster.filter(e=>($('zone').value==='All India'||e.zone===$('zone').value)&&($('status').value==='All'||e.status===$('status').value))}
function pairs(es,tech=$('tech').value){return es.flatMap(e=>T.filter(t=>tech==='All technologies'||t===tech).map(t=>({e,t,level:e.levels[T.indexOf(t)],ft:e.ft[T.indexOf(t)],base:e.base[T.indexOf(t)]})))}
function records(es,tech=$('tech').value,period=true){let ids=new Set(es.map(e=>e.id));return DATA.events.filter(x=>ids.has(x.id)&&(tech==='All technologies'||x.tech===tech)&&(!period||$('month').value==='All months'||x.month===$('month').value))}
function metrics(ps,ev){let unique=new Map();ps.forEach(p=>unique.set(p.e.id,p.ft));let f=[...unique.values()].filter(x=>x!==null),r=ev.filter(e=>e.type==='resolution'),days=r.map(e=>e.days).filter(x=>x!==null),valid=r.filter(x=>x.hit!==null);return {ft:mean(f),fn:f.length,days:mean(days),n:r.length,dn:days.length,esc:ev.filter(x=>x.type==='escalation').length,otd:valid.length?valid.filter(x=>x.hit).length/valid.length:null}}
function table(headers,rows){return `<table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="empty">No records in this scope.</td></tr>`}</tbody></table>`}
function cohort(ps,ev,l){let pp=ps.filter(p=>p.level===l),keys=new Set(pp.map(p=>p.e.id+'|'+p.t)),ee=ev.filter(x=>keys.has(x.id+'|'+x.tech));return {...metrics(pp,ee),count:new Set(pp.map(p=>p.e.id)).size,assessments:pp.length}}
let exportRows=[];
function render(){let es=scope(),ps=pairs(es),ev=records(es),m=metrics(ps,ev),co=L.map(l=>cohort(ps,ev,l));
 $('cards').innerHTML=[['Engineers in scope',fmt(es.length,0),'Current roster · '+$('status').value],['First-time fix rate',pct(m.ft),`${m.fn} engineers · undated snapshot`],['Avg. resolution',m.days==null?'—':fmt(m.days)+' d',`${m.dn} valid work items · ${$('month').value}`],['Escalations',fmt(m.esc,0),'Distinct case / work-item appointments']].map((x,i)=>`<article class="card"><small>${x[0]} <span style="float:right;color:#64907a">${['◈','↗','◷','⚑'][i]}</span></small><div class="value">${x[1]}</div><footer>${x[2]}</footer></article>`).join('');
 $('cohorts').innerHTML=table(['Certification','Engineers','FTFR','Resolution','Work items','Escalations'],L.map((l,i)=>[l,co[i].count,pct(co[i].ft),co[i].days==null?'—':fmt(co[i].days)+' d',co[i].n,co[i].esc]));
 let total=ps.length; $('distribution').innerHTML=`<div class="stack">${L.map((l,i)=>`<span style="width:${total?co[i].assessments/total*100:0}%;background:${C[i]}" title="${l}: ${co[i].assessments}"></span>`).join('')}</div><div class="levels">${L.map((l,i)=>`<div class="level"><small>${l}</small><strong>${co[i].assessments}</strong></div>`).join('')}</div>`;
 let base=ps.reduce((s,p)=>s+p.base,0),covered=ps.filter(p=>p.level!=='Unassessed').reduce((s,p)=>s+p.base,0);$('coverage').innerHTML=`<strong>${pct(base?covered/base:null)} assessed installed-base coverage</strong><br>${fmt(covered,0)} of ${fmt(base,0)} installed units have a recorded certification assessment.`;
 let ts=T.filter(t=>$('tech').value==='All technologies'||t===$('tech').value);$('technologies').innerHTML=table(['Technology','L3 / assessed','FTFR','Avg. days','OTD'],ts.map(t=>{let p=pairs(es,t),ee=records(es,t),mm=metrics(p,ee);return [t,`${p.filter(x=>x.level==='Level 3').length} / ${p.filter(x=>x.level!=='Unassessed').length}`,pct(mm.ft),fmt(mm.days),pct(mm.otd)]}));
 $('zones').innerHTML=[...new Set(es.map(e=>e.zone))].sort().map(z=>{let p=ps.filter(x=>x.e.zone===z);return `<div class="barrow"><span>${esc(z)}</span><div class="stack">${L.map((l,i)=>{let n=p.filter(x=>x.level===l).length;return `<span style="width:${n/p.length*100}%;background:${C[i]}" title="${esc(z)} · ${l}: ${n}">${n||''}</span>`}).join('')}</div><b>${p.length}</b></div>`}).join('')+`<div class="legend">${L.map((l,i)=>`<span><i class="dot" style="background:${C[i]}"></i>${l}</span>`).join('')}</div>`;
 let all=records(es,$('tech').value,false).filter(x=>x.type==='resolution'),months=[...new Set(all.map(x=>x.month))].sort(),points=months.map(month=>{let a=all.filter(x=>x.month===month&&x.days!==null);return {month,v:mean(a.map(x=>x.days)),n:a.length}}),max=Math.max(1,...points.map(x=>x.v||0));
 $('trend').innerHTML=points.length?`<svg viewBox="0 0 1000 170" role="img" aria-label="Monthly average resolution days">${[0,.5,1].map(v=>`<line x1="35" y1="${125-v*100}" x2="980" y2="${125-v*100}" stroke="#e7ece6"/><text x="0" y="${130-v*100}" font-size="10" fill="#70827b">${fmt(v*max)}</text>`).join('')}<polyline fill="none" stroke="#29836a" stroke-width="3" points="${points.map((p,i)=>`${60+i*900/Math.max(1,points.length-1)},${125-(p.v||0)/max*100}`).join(' ')}"/>${points.map((p,i)=>`<circle cx="${60+i*900/Math.max(1,points.length-1)}" cy="${125-(p.v||0)/max*100}" r="5" fill="${$('month').value===p.month?'#d9a748':'#29836a'}"><title>${p.month}: ${fmt(p.v)} days · ${p.n} work items</title></circle><text x="${60+i*900/Math.max(1,points.length-1)}" y="155" text-anchor="middle" font-size="10" fill="#70827b">${p.month.slice(5)}</text>`).join('')}</svg>`:'<div class="empty">No monthly records in this scope.</div>';
 $('recommendations').innerHTML=table(['Technology','Lowest observed level meeting targets','Evidence'],ts.map(t=>{let pp=pairs(es,t),ee=records(es,t),cs=L.slice(0,3).map(l=>({l,...cohort(pp,ee,l)})),win=cs.find(c=>c.fn>=+$('minTarget').value&&c.count>=+$('minTarget').value&&c.dn>=+$('minTarget').value&&c.ft>=+$('ftTarget').value/100&&c.days!=null&&c.days<=+$('dayTarget').value);return [t,win?`<span class="pill">${win.l}</span>`:'No supported level',win?`${win.count} engineers · ${win.dn} work items`:'Targets unmet or sample too small']}));
 let usable=co.slice(0,3).filter(c=>c.ft!=null&&c.days!=null),best=usable.length?L[co.indexOf(usable.reduce((a,b)=>a.days<b.days?a:b))]:null;
 $('insights').innerHTML=`<div class="insight"><strong>${best?best+' has the shortest observed resolution':'Insufficient cohort evidence'}</strong>${best?'Within the selected scope. Compare work-item counts and case complexity before choosing a training level.':'Expand filters to compare certification cohorts.'}</div><div class="insight"><strong>FTFR is a snapshot, not a monthly trend</strong>Repeated technology rates and missing job denominators limit the strength of the certification relationship.</div><div class="insight"><strong>Financial ROI needs additional inputs</strong>Add training spend, contribution per saved visit, engineer workload and certification dates to quantify investment returns.</div>`;
 let q=$('search').value.toLowerCase();exportRows=es.filter(e=>(e.name+' '+e.manager).toLowerCase().includes(q)).map(e=>{let p=ps.filter(x=>x.e.id===e.id),mm=metrics(p,ev.filter(x=>x.id===e.id));return [e.name,e.zone,e.status,p.map(x=>x.t+': '+x.level).join(' / '),pct(mm.ft),fmt(mm.days),mm.n,mm.esc]});$('engineerTable').innerHTML=table(['Engineer','Zone','Status','Assessments','FTFR','Days','Items','Escalations'],exportRows.map(r=>r.map(esc)));
 let a=DATA.audit;$('audit').innerHTML=`<div class="notice">${DATA.roster.length} reconciled engineers · ${a.sourceResolution} source resolution rows · ${a.sourceEscalation} source escalation rows · ${a.unmatched.length} unmatched source rows excluded from linked analysis · ${a.duplicateEvents} repeated event rows excluded · ${a.duplicateRoster.length} duplicate roster names flagged.</div>`;let issues=new Map();a.unmatched.forEach(x=>{let k=x.source+'|'+x.name;issues.set(k,{...x,n:(issues.get(k)?.n||0)+1})});$('issues').innerHTML=table(['Source','Unmatched name','Rows'],[...issues.values()].map(x=>[esc(x.source),esc(x.name||'(blank)'),x.n]))+table(['Duplicate roster name','Source row'],a.duplicateRoster.map(x=>[esc(x.name),x.row]));
}
['zone','tech','month','status','ftTarget','dayTarget','minTarget','search'].forEach(id=>$(id).addEventListener('input',render));$('reset').onclick=()=>{['zone','tech','month','status'].forEach(id=>$(id).selectedIndex=0);$('search').value='';render()};$('export').onclick=()=>{let rows=[['Engineer','Zone','Status','Assessments','FTFR','Days','Items','Escalations'],...exportRows],csv=rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n'),u=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='service-engineer-analysis.csv';a.click();URL.revokeObjectURL(u)};render();
